# Prototype: shared git-invocation scanner.
#
# skip_global_opts(tokens, start, n) is the ONE shared routine: given a
# token array and a starting index, skip any run of global option tokens
# (anything starting with "-", plus the following bare value for the
# space-separated value-taking forms) and return the index of the first
# non-option token (the subcommand). Populates CVALS[1..NCVALS] with any
# -C values seen, in left-to-right order, as a side effect.
function is_global_valued(opt) {
    return (opt == "-C" || opt == "-c" || opt == "--git-dir" || \
            opt == "--work-tree" || opt == "--namespace" || opt == "--exec-path")
}

function skip_global_opts(tokens, start, n,    i) {
    NCVALS = 0
    i = start
    while (i <= n) {
        if (substr(tokens[i], 1, 1) != "-") {
            return i
        }
        if (is_global_valued(tokens[i])) {
            if (tokens[i] == "-C" && i < n) {
                NCVALS++
                CVALS[NCVALS] = tokens[i + 1]
            }
            i += 2
        } else {
            i += 1
        }
    }
    return 0
}

function is_hazard_word(w) {
    return (w == "if" || w == "then" || w == "elif" || w == "fi" || \
            w == "while" || w == "until" || w == "case" || w == "esac" || \
            w == "done" || w == "pushd")
}

# MODE dispatch: classify | pushargs | scope
BEGIN {
    buf = ""
}
{ buf = buf $0 "\n" }
END {
    text = buf
    pos = 1
    n = length(text)
    hazard = 0
    nchain = 0
    npush = 0

    while (pos <= n) {
        rest = substr(text, pos)
        # Find earliest of: ||  &&  ;  |  (  )  \n
        best = -1
        bestlen = 0
        bestsep = ""
        split("|| && ; | ( ) \n", septest, " ")
        # handle literal newline specially since split-by-space mangles it
        seps[1] = "||"; seps[2] = "&&"; seps[3] = ";"; seps[4] = "|"; seps[5] = "("; seps[6] = ")"; seps[7] = "\n"
        for (si = 1; si <= 7; si++) {
            sp = seps[si]
            idx = index(rest, sp)
            if (idx > 0 && (best == -1 || idx < best || (idx == best && length(sp) > bestlen))) {
                # prefer longer separators at same position (|| over |)
                if (idx < best || best == -1) {
                    best = idx; bestlen = length(sp); bestsep = sp
                } else if (idx == best && length(sp) > bestlen) {
                    best = idx; bestlen = length(sp); bestsep = sp
                }
            }
        }

        if (best == -1) {
            stmt = rest
            sep = ""
            advance = length(rest) + 1
        } else {
            stmt = substr(rest, 1, best - 1)
            sep = bestsep
            advance = best - 1 + length(sep)
        }

        # Trim leading/trailing whitespace from stmt for classification
        trimmed = stmt
        gsub(/^[ \t]+/, "", trimmed)
        gsub(/[ \t]+$/, "", trimmed)

        if (trimmed != "") {
            nt = split(trimmed, toks, /[ \t]+/)
            if (nt > 0) {
                if (toks[1] == "cd" && !hazard) {
                    if (nt >= 2) {
                        nchain++
                        chain[nchain] = toks[2]
                    }
                } else if (is_hazard_word(toks[1])) {
                    hazard = 1
                } else if (toks[1] == "git" || (toks[1] ~ /^[A-Za-z_][A-Za-z0-9_]*=/)) {
                    # possible env assignments before git; skip them
                    gi = 1
                    while (gi <= nt && toks[gi] ~ /^[A-Za-z_][A-Za-z0-9_]*=/) gi++
                    if (gi <= nt && toks[gi] == "git") {
                        sub_idx = skip_global_opts(toks, gi + 1, nt)
                        if (sub_idx > 0 && toks[sub_idx] == "push") {
                            npush++
                            push_hazard[npush] = hazard
                            push_nchain_cvals = NCVALS
                            # snapshot chain + this invocation's own -C vals
                            pc = ""
                            for (ci = 1; ci <= nchain; ci++) pc = pc chain[ci] "\x1f"
                            for (ci = 1; ci <= NCVALS; ci++) pc = pc CVALS[ci] "\x1f"
                            push_chain[npush] = pc
                            argstr = ""
                            for (ai = sub_idx + 1; ai <= nt; ai++) argstr = argstr (ai > sub_idx+1 ? " " : "") toks[ai]
                            push_args[npush] = argstr
                        }
                    }
                }
            }
        }

        if (sep == "||" || sep == "(") hazard = 1

        pos += advance
        if (advance <= 0) break
    }

    for (p = 1; p <= npush; p++) {
        print "PUSH " p " hazard=" push_hazard[p] " args=[" push_args[p] "] chain=[" push_chain[p] "]"
    }
    if (npush == 0) print "NONE"
}

# Prototype commit-1 engine: quote-aware tokenizer + shared global-option
