function tokenize_line(line,    i, n, c, cur, in_tok, qc, j) {
    i = 1
    n = length(line)
    cur = ""
    in_tok = 0
    while (i <= n) {
        c = substr(line, i, 1)
        if (c == " " || c == "\t") {
            if (in_tok) { NTOK++; TOKENS[NTOK] = cur; cur = ""; in_tok = 0 }
            i++
            continue
        }
        if (c == "&" && substr(line, i, 2) == "&&") {
            if (in_tok) { NTOK++; TOKENS[NTOK] = cur; cur = ""; in_tok = 0 }
            NTOK++; TOKENS[NTOK] = "&&"
            i += 2
            continue
        }
        if (c == "|" && substr(line, i, 2) == "||") {
            if (in_tok) { NTOK++; TOKENS[NTOK] = cur; cur = ""; in_tok = 0 }
            NTOK++; TOKENS[NTOK] = "||"
            i += 2
            continue
        }
        if (c == ";" || c == "|" || c == "(" || c == ")") {
            if (in_tok) { NTOK++; TOKENS[NTOK] = cur; cur = ""; in_tok = 0 }
            NTOK++; TOKENS[NTOK] = c
            i++
            continue
        }
        if (c == "\"" || c == "'") {
            qc = c
            j = i + 1
            while (j <= n) {
                if (qc == "\"" && substr(line, j, 1) == "\\" && j < n) { j += 2; continue }
                if (substr(line, j, 1) == qc) break
                j++
            }
            if (j > n) {
                cur = cur substr(line, i + 1)
                in_tok = 1
                i = n + 1
                continue
            }
            cur = cur substr(line, i + 1, j - i - 1)
            in_tok = 1
            i = j + 1
            continue
        }
        cur = cur c
        in_tok = 1
        i++
    }
    if (in_tok) { NTOK++; TOKENS[NTOK] = cur }
    NTOK++; TOKENS[NTOK] = ";"
