        next
    }
    if (match(line, /<<-?[[:space:]]*['"]?[A-Za-z_][A-Za-z0-9_]*['"]?/)) {
        op = substr(line, RSTART, RLENGTH)
        before = substr(line, 1, RSTART - 1)
        strip_tabs = (op ~ /^<<-/)
        delimword = op
        sub(/^<<-?[[:space:]]*/, "", delimword)
        gsub(/['"]/, "", delimword)
        delim = delimword
        in_heredoc = 1
        tokenize_line(before)
