    }
    tokenize_line(line)
}
END {
    hazard = 0
    first = 1
    env_ok = 1
    expect_c = 0
    in_git = 0
    found_sub = 0
    is_push = 0
    npush = 0
    args = ""
    i = 1
    while (i <= NTOK) {
        t = TOKENS[i]
        if (t == "&&" || t == ";") {
            first = 1; env_ok = 1; in_git = 0; found_sub = 0; is_push = 0
            i++; continue
        }
        if (t == "||" || t == "(" || t == ")") {
            hazard = 1
            first = 1; env_ok = 1; in_git = 0; found_sub = 0; is_push = 0
            i++; continue
        }
        if (first) {
            if (env_ok && t ~ /^[A-Za-z_][A-Za-z0-9_]*=/) {
                i++; continue
            }
            env_ok = 0
            if (is_hazard_word(t)) { hazard = 1; first = 0; i++; continue }
            if (t == "git") { in_git = 1; found_sub = 0; is_push = 0; expect_c = 0; first = 0; i++; continue }
            first = 0; i++; continue
        }
        if (in_git && !found_sub) {
            if (expect_c) { expect_c = 0; i++; continue }
            if (substr(t, 1, 1) == "-") {
                if (is_global_valued(t)) expect_c = 1
                i++; continue
            }
            found_sub = 1
            if (t == "push") { is_push = 1; npush++; args = "" }
            i++; continue
        }
        if (in_git && found_sub && is_push) {
            args = (args == "" ? t : args " " t)
        }
        i++
        if (i > NTOK || TOKENS[i] == "&&" || TOKENS[i] == ";" || TOKENS[i] == "||" || TOKENS[i] == "(" || TOKENS[i] == ")") {
            if (is_push) print "ARGS " args
            is_push = 0
        }
    }
    print "HAZARD " hazard
    print "PUSHCOUNT " npush
}

