# Prototype of the shared git-invocation scanner. Buffers whole stdin,
# tokenizes it (quote-aware, treating &&, ||, ;, |, (, ), and newline as
# separate operator tokens), then walks the token stream for every `git`
# invocation in command position and reports push invocations found.
function strip_one_quote(v,    first, last) {
    if (length(v) >= 2) {
        first = substr(v, 1, 1)
        last = substr(v, length(v), 1)
        if ((first == "\"" && last == "\"") || (first == "'" && last == "'")) {
            return substr(v, 2, length(v) - 2)
        }
    }
    return v
}

function is_global_valued(opt) {
    return (opt == "-C" || opt == "-c" || opt == "--git-dir" || \
            opt == "--work-tree" || opt == "--namespace" || opt == "--exec-path")
}

# tok[1..n] are tokens starting right after the `git` token (tok[start]
# is the first candidate). Returns the index of the subcommand (first
# non-option token), or 0 if none found before n. Fills CVALS[1..NCVALS]
# with each -C value seen, in left-to-right order.
function skip_global_opts(tok, start, n,    i) {
    NCVALS = 0
    i = start
    while (i <= n) {
        if (substr(tok[i], 1, 1) != "-") {
            return i
        }
        if (is_global_valued(tok[i])) {
            if (tok[i] == "-C" && i < n) {
                NCVALS++
                CVALS[NCVALS] = strip_one_quote(tok[i + 1])
            }
            i += 2
        } else {
            i += 1
        }
    }
    return 0
}

function is_env_assign(t) {
