# Combined git-invocation scanner prototype (round 2).
#
# One tokenizer + one skip_global_opts routine, consumed to emit, for every
# git-push invocation found in command position: whether it is bare, its
# own -C-derived directory (if any), its positional args (for ref check),
# and a global ambiguity flag (subshell/conditional/pushd anywhere in text).
# Also finds, for a push with no own -C, the last unconditional `cd` target
# appearing before that push's `git` token, scanning across the whole token
# stream (so a `cd` on one line and `push` on the next are both seen).
function strip_one_quote(v,    first, last) {
    if (length(v) >= 2) {
        first = substr(v, 1, 1)
        last = substr(v, length(v), 1)
        if ((first == "\"" && last == "\"") || (first == "'" && last == "'")) {
            return substr(v, 2, length(v) - 2)
        }
    }
    return v
}

function is_global_valued(opt) {
    return (opt == "-C" || opt == "-c" || opt == "--git-dir" || \
            opt == "--work-tree" || opt == "--namespace" || opt == "--exec-path")
