# first non-option token (the subcommand), or 0 if none before n. Fills
# CVALS[1..NCVALS] with each -C value seen, in left-to-right order.
function skip_global_opts(tok, start, n,    i) {
    NCVALS = 0
    i = start
    while (i <= n) {
        if (substr(tok[i], 1, 1) != "-") {
            return i
        }
        if (is_global_valued(tok[i])) {
            if (tok[i] == "-C" && i < n) {
                NCVALS++
                CVALS[NCVALS] = strip_one_quote(tok[i + 1])
            }
            i += 2
        } else {
            i += 1
        }
    }
    return 0
}

function is_env_assign(t) {
    return (t ~ /^[A-Za-z_][A-Za-z0-9_]*=/)
}

function is_separator(t) {
    return (t == "&&" || t == "||" || t == ";" || t == "|" || t == "(" || t == ")" || t == "\n")
}

function is_ambiguous_tok(t) {
    return (t == "(" || t == ")" || t == "||" || t == "if" || t == "then" || \
            t == "elif" || t == "else" || t == "fi" || t == "pushd" || t == "popd")
}

