                   in_heredoc, delim, strip_tabs, line_start, lineend, \
                   op_start, op_end, op, delimword, before_nl) {
    NT = 0
    n = length(text)
    i = 1
    cur = ""
    in_heredoc = 0
    delim = ""
    strip_tabs = 0
