                line_start = substr(text, i)
                i = n + 1
            } else {
                line_start = substr(text, i, lineend - 1)
                i = i + lineend
            }
            before_nl = line_start
            if (strip_tabs) sub(/^\t+/, "", before_nl)
            if (before_nl == delim) {
                in_heredoc = 0
                delim = ""
                strip_tabs = 0
            }
            continue
