# For git invocation starting at TOK[gi]=="git", find subcommand index
# (via skip_global_opts) and, if "push", print one PUSH record.
function emit_if_push(gi,    s, cvlist, cv, k, e, positional, tok1, bare, \
                       lastdir, scan_i, found_push_here) {
    s = skip_global_opts(TOK, gi + 1, NT)
    if (s == 0 || TOK[s] != "push") return
    cvlist = ""
    for (cv = 1; cv <= NCVALS; cv++) cvlist = cvlist (cv > 1 ? "," : "") CVALS[cv]
    e = s + 1
    while (e <= NT && !is_separator(TOK[e])) e++
    positional = 0
    args = ""
    for (k = s + 1; k < e; k++) {
        if (substr(TOK[k], 1, 1) != "-") positional++
        args = args TOK[k] (k < e - 1 ? " " : "")
    }
    bare = (positional == 0)
    if (positional == 1) {
        # Single positional token with no ":" is a bare remote-only push
        # (push.default decides what gets pushed); a token containing ":"
        # is an explicit refspec even alone (e.g. HEAD:main).
        tok1 = ""
        for (k = s + 1; k < e; k++) {
            if (substr(TOK[k], 1, 1) != "-") { tok1 = TOK[k]; break }
        }
        if (tok1 !~ /:/) bare = 1
    }

    lastdir = ""
    if (cvlist == "") {
        scan_i = gi - 1
        while (scan_i >= 1) {
            if (TOK[scan_i] == "cd" && (scan_i == 1 || is_separator(TOK[scan_i - 1]))) {
                k = scan_i + 1
                if (k <= NT && !is_separator(TOK[k])) {
                    lastdir = TOK[k]
                }
                break
            }
            scan_i--
        }
    }

    printf "PUSH bare=%d cvals=%s cddir=%s args=[%s]\n", bare, \
        (cvlist == "" ? "-" : cvlist), (lastdir == "" ? "-" : lastdir), args
