function scan_pushes(   i, j) {
    for (i = 1; i <= NT; i++) {
        if (TOK[i] != "git") continue
        j = i - 1
        while (j >= 1 && is_env_assign(TOK[j])) j--
        if (j >= 1 && !is_separator(TOK[j])) continue
        emit_if_push(i)
    }
}

BEGIN { buf = "" }
{ buf = buf $0 "\n" }
END {
    tokenize(buf)
    printf "AMBIGUOUS%c%d\n", 31, scan_ambiguous()
    scan_pushes()
}

